    'piano_learners' => [
        'meta_title' => 'Harmoniva pour les pianistes en formation',
        'meta_description' => 'Faites progresser votre piano grâce à l\'oreille : reconnaissez intervalles, accords et mélodies à l\'oreille et jouez en toute liberté.',
