    'ear_guide' => [
        'meta_title' => 'Le guide complet de la formation de l\'oreille',
        'meta_description' => 'Guide complet de la formation de l\'oreille, chapitre par chapitre : des bases aux techniques avancées — quoi travailler, comment, et pourquoi.',
        'jsonld_headline' => 'Le guide complet de la formation de l\'oreille',
        'jsonld_description' => 'Un guide complet, chapitre par chapitre, sur la formation de l\'oreille — des bases absolues aux techniques avancées.',
        'jsonld_about' => 'Formation de l\'oreille',
        'jsonld_home' => 'Accueil',
        'hero_badge' => 'Guide gratuit',
        'hero_title' => 'Le guide complet de la formation de l\'oreille',
        'hero_subtitle' => 'De votre premier intervalle à la dictée mélodique avancée — tout ce qu\'il faut pour bâtir une oreille musicale de premier plan, expliqué clairement et concrètement.',
        'hero_stat_1' => '25 min de lecture',
        'hero_stat_2' => '6 chapitres',
        'hero_stat_3' => 'Tous niveaux',
        'toc_title' => 'Sommaire',
        'toc_1' => 'Qu\'est-ce que la formation de l\'oreille ?',
        'toc_2' => 'Pourquoi la formation de l\'oreille compte',
        'toc_3' => 'Compétences clés — intervalles, accords, gammes, rythme',
        'toc_4' => 'Comment travailler efficacement',
        'toc_5' => 'Technologie & IA dans la formation de l\'oreille',
        'toc_6' => 'Du débutant à l\'avancé — votre feuille de route',
        'takeaway_label' => 'À retenir',
        'h1' => 'Qu\'est-ce que la formation de l\'oreille ?',
        'ch1_p1' => 'La formation de l\'oreille — aussi appelée formation musicale ou solfège — est le travail systématique de votre écoute musicale. C\'est le processus qui consiste à apprendre à identifier, reproduire et comprendre les éléments musicaux uniquement par l\'écoute, sans dépendre d\'une partition ni d\'un instrument entre les mains.',
        'ch1_p2' => 'Quand un musicien professionnel entend un enchaînement d\'accords et le nomme instantanément, transcrit une mélodie entendue une seule fois ou accorde son instrument à l\'oreille dans une pièce bruyante — c\'est le fruit de la formation de l\'oreille. Ces capacités ne sont pas un don réservé aux plus doués : ce sont des compétences qui s\'apprennent et qui répondent à un travail régulier et ciblé.',
        'ch1_p3' => 'Au fond, la formation de l\'oreille apprend à votre cerveau à donner du sens au son. Vous apprenez à entendre les relations entre les notes (intervalles), la qualité des combinaisons de notes (accords), les schémas d\'ensembles de hauteurs organisés (gammes) et la structure du temps (rythme). Ensemble, ces quatre piliers forment le socle complet de l\'écoute musicale.',
        'ch1_takeaway' => 'La formation de l\'oreille est une compétence qui s\'apprend — pas un talent. Tous les musiciens professionnels l\'ont travaillée, et vous le pouvez aussi. La clé est de savoir quoi travailler et de tenir dans la durée.',
        'cta1_title' => 'Prêt à identifier vos premiers intervalles ?',
        'cta1_desc' => 'Les exercices d\'intervalles d\'Harmoniva partent de zéro — aucune base de théorie musicale requise.',
        'cta1_button' => 'Essayer gratuitement',
        'h2' => 'Pourquoi la formation de l\'oreille compte pour tout musicien',
        'ch2_p1' => 'Quels que soient votre instrument, votre style ou vos objectifs, la formation de l\'oreille est la compétence qui sépare les musiciens dépendants de la partition posée devant eux de ceux qui entendent, comprennent et expriment vraiment la musique. Ce n\'est pas une matière réservée aux étudiants de conservatoire — c\'est le socle de toutes les disciplines musicales.',
        'ch2_p2' => 'Pour l\'improvisateur, une oreille exercée signifie entendre où la musique veut aller avant même de jouer une note. Pour l\'auteur-compositeur, c\'est traduire directement à l\'instrument les mélodies qu\'il a en tête. Pour le producteur, c\'est identifier pourquoi un mix sonne brouillon et comment le corriger précisément. Pour le musicien d\'orchestre, c\'est rester juste avec son pupitre même quand l\'acoustique change en pleine représentation.',
        'ch2_p3' => 'La recherche en psychologie de la musique montre systématiquement que les musiciens qui travaillent leur oreille développent une meilleure mémoire musicale, apprennent plus vite un nouveau répertoire et improvisent avec plus d\'aisance. Cet investissement rapporte dans tous les autres domaines de votre vie musicale.',
        'ch2_b1_title' => 'Apprendre plus vite',
        'ch2_b1_desc' => 'Reconnaissez les schémas instantanément et montez un nouveau morceau en moins de temps.',
        'ch2_b2_title' => 'Mieux jouer en public',
        'ch2_b2_desc' => 'Restez juste et réagissez aux autres musiciens en temps réel.',
        'ch2_b3_title' => 'Créer davantage',
        'ch2_b3_desc' => 'Faites passer vos idées musicales de l\'imagination à la réalité.',
        'ch2_takeaway' => 'La formation de l\'oreille n\'a rien d\'académique. Elle améliore directement et immédiatement votre jeu, votre composition et votre communication musicale — quel que soit le style que vous pratiquez.',
        'h3' => 'Compétences clés — intervalles, accords, gammes & rythme',
        'skill_intervals_title' => 'Intervalles',
        'skill_intervals_desc' => 'Un intervalle est la distance entre deux notes, mesurée en demi-tons. Il existe douze intervalles à l\'intérieur d\'une octave, de la seconde mineure (un demi-ton) à l\'octave (douze demi-tons). Apprendre à identifier les intervalles est la compétence au meilleur rendement de toute la formation de l\'oreille, car la reconnaissance des intervalles sous-tend tout le reste : les accords sont des empilements d\'intervalles, les gammes des suites d\'intervalles, et les mélodies se déplacent par intervalles. Les moyens mnémotechniques classiques (associer une tierce mineure au début de « Smoke on the Water ») aident les débutants, mais l\'objectif final reste la reconnaissance directe, sans morceau de référence.',
        'skill_chords_title' => 'Accords',
        'skill_chords_desc' => 'Un accord, ce sont trois notes ou plus qui sonnent simultanément. Les types les plus courants — majeur, mineur, diminué, augmenté, septième de dominante, septième majeure, septième mineure — possèdent chacun une « couleur » sonore reconnaissable de façon fiable. La clé de l\'identification des accords est d\'entraîner votre oreille à percevoir l\'ambiance et la tension globales du son, pas seulement les notes individuelles. Les renversements ajoutent un niveau de complexité, car le même accord sonne subtilement différemment selon la note placée à la basse.',
        'skill_scales_title' => 'Gammes',
        'skill_scales_desc' => 'Les gammes sont des suites organisées de notes qui définissent le « port d\'attache » tonal d\'un morceau. Les gammes majeures et mineures sont les plus fondamentales, mais les gammes modales (dorien, phrygien, lydien, mixolydien, etc.) sont essentielles au jazz, aux musiques traditionnelles et aux musiques du monde. Les gammes pentatoniques se retrouvent partout, du blues à la musique classique chinoise. Entraîner votre oreille à reconnaître les gammes en contexte vous aide à comprendre pourquoi un morceau sonne ainsi et comment y naviguer harmoniquement.',
        'skill_rhythm_title' => 'Rythme',
        'skill_rhythm_desc' => 'Le travail rythmique de l\'oreille est souvent négligé, alors qu\'il compte tout autant. Il s\'agit d\'apprendre à identifier les chiffrages de mesure, les valeurs de notes et les motifs rythmiques — et, à terme, de savoir noter de zéro les rythmes que vous entendez. Beaucoup de musiciens ont une excellente discrimination des hauteurs mais butent sur les rythmes complexes. Un travail rythmique régulier — frapper dans les mains, compter à voix haute, jouer avec un métronome — construit l\'horloge interne qui rend tout le reste naturel.',
        'ch3_takeaway' => 'Commencez par les intervalles avant de passer aux accords et aux gammes. Une base solide en intervalles fait tomber tout le reste en place bien plus vite.',
        'cta2_title' => 'Travaillez les quatre compétences clés sur Harmoniva',
        'cta2_desc' => 'Intervalles, accords, gammes et rythme — tout est couvert par des exercices adaptatifs qui partent de votre niveau.',
        'cta2_button' => 'Commencer gratuitement',
        'h4' => 'Comment travailler efficacement',
        'ch4_p1' => 'Le principe le plus important du travail de l\'oreille est la régularité plutôt que l\'intensité. De courtes séances quotidiennes de 10 à 15 minutes surpasseront à chaque fois une séance marathon de deux heures le dimanche. Votre cerveau consolide les nouveaux circuits auditifs pendant le sommeil : une exposition fréquente suivie de repos est donc le rythme d\'apprentissage optimal.',
        'ch4_p2' => 'Concentrez-vous sur une compétence à la fois jusqu\'à atteindre un taux de réussite fiable (80–90 %) avant d\'en ajouter une autre. Beaucoup de débutants essaient d\'apprendre tous les types d\'intervalles en même temps et finissent par tout mélanger. Maîtrisez plutôt la quinte juste et l\'octave d\'abord, ajoutez ensuite la tierce majeure et la tierce mineure, puis construisez à partir de là. Cette approche progressive paraît plus lente mais donne des résultats durables plus rapidement.',
        'ch4_p3' => 'Ne travaillez pas uniquement dans une application. Emmenez ce que vous apprenez dans le monde réel. Écoutez des enregistrements et essayez d\'identifier les accords. Jouez des gammes sur votre instrument et observez leur couleur. Chantez les intervalles avant de les jouer. C\'est dans cette boucle entre séances de travail et écoute musicale active que se produit l\'apprentissage profond.',
        'routine_title' => 'Exemple de routine quotidienne (15 minutes)',
        'routine_1_time' => '3 min',
        'routine_1_text' => 'Échauffement — chantez une gamme majeure de mémoire, puis une gamme mineure',
        'routine_2_time' => '5 min',
        'routine_2_text' => 'Identification d\'intervalles — intervalles mélodiques, en ciblant vos 2 types les plus faibles',
        'routine_3_time' => '4 min',
        'routine_3_text' => 'Qualité des accords — distinguer majeur et mineur, fondamentales aléatoires',
        'routine_4_time' => '3 min',
        'routine_4_text' => 'Rythme — reproduisez en frappant une série de motifs de 4 mesures sans ralentir',
        'ch4_takeaway' => '15 minutes chaque jour valent mieux que 2 heures une fois par semaine. Concevez un travail tenable, pas héroïque.',
        'h5' => 'Utiliser la technologie et l\'IA dans la formation de l\'oreille',
        'ch5_p1' => 'La technologie a transformé la formation de l\'oreille au cours de la dernière décennie. Là où il fallait autrefois un professeur au piano pour faire répéter la reconnaissance d\'intervalles, les applications d\'aujourd\'hui génèrent une infinité d\'exercices uniques, suivent vos réponses et s\'adaptent en temps réel. Ce n\'est pas seulement pratique — pour beaucoup d\'élèves, c\'est un réel progrès par rapport aux méthodes traditionnelles.',
        'ch5_p2' => 'Les plateformes propulsées par l\'IA vont plus loin : elles analysent vos schémas d\'erreurs sur des centaines de séances et orientent intelligemment les questions suivantes vers vos points faibles. Les applications classiques traitent tous les intervalles comme aussi importants et les font défiler uniformément. Une IA adaptative remarque que vous confondez les sixtes mineures et majeures bien plus que toute autre paire, et augmente automatiquement la fréquence de ces comparaisons précises jusqu\'à ce que votre précision progresse.',
        'ch5_p3' => 'La meilleure approche associe la technologie à une écoute musicale active. Servez-vous d\'une application pour le travail structuré, mais prenez aussi l\'habitude d\'écouter des enregistrements avec l\'objectif explicite d\'identifier ce que vous entendez. Essayez de deviner l\'accord dès qu\'un nouveau morceau démarre. Transcrivez une courte mélodie à l\'oreille. Ces « séances d\'application » ancrent dans un contexte musical réel les compétences que l\'application fait répéter — et c\'est là qu\'elles deviennent vraiment durables.',
        'ch5_takeaway' => 'L\'IA ne remplace pas le travail délibéré — elle le rend plus efficace en supprimant les hésitations sur ce qu\'il faut travailler ensuite.',
        'h6' => 'Du débutant à l\'avancé — votre feuille de route',
        'ch6_p1' => 'Les progrès en formation de l\'oreille suivent une courbe prévisible. Les débutants commencent en général par distinguer majeur et mineur et par identifier les grands intervalles (octaves et quintes). Après quelques semaines de travail quotidien, la plupart identifient de façon fiable les douze intervalles. L\'attention se déplace ensuite vers la qualité des accords, puis vers des compétences plus fines : renversements, modes, et enfin dictée mélodique.',
        'ch6_p2' => 'Le plateau intermédiaire — où vous identifiez facilement les intervalles isolés mais peinez en contexte musical — est le point de blocage le plus fréquent. La solution est de travailler sur de vrais exemples musicaux, pas seulement sur des sons générés par ordinateur. Écoutez comment les intervalles apparaissent au sein d\'une phrase, comment les enchaînements d\'accords créent tension et résolution, comment le feeling rythmique diffère d\'un style à l\'autre.',
        'ch6_p3' => 'La formation avancée de l\'oreille ne s\'arrête jamais vraiment — même les professionnels continuent d\'affiner leur écoute toute leur carrière. Mais vous saurez avoir atteint le niveau avancé quand vous pourrez vous asseoir au piano, écouter une chanson une seule fois et en restituer fidèlement l\'enchaînement d\'accords ; quand vous transcrirez une mélodie au premier ou au deuxième passage ; et quand votre jeu reflétera votre écoute intérieure immédiatement et sans effort.',
        'level_beg_title' => 'Débutant',
        'level_beg_period' => '0–3 mois',
        'level_beg_1' => 'Identification des intervalles mélodiques (les 12)',
        'level_beg_2' => 'Accords majeurs et mineurs',
        'level_beg_3' => 'Motifs rythmiques simples',
        'level_beg_4' => 'Reconnaissance de notes isolées',
        'level_int_title' => 'Intermédiaire',
        'level_int_period' => '3–12 mois',
        'level_int_1' => 'Intervalles harmoniques',
        'level_int_2' => 'Tous les types d\'accords + renversements',
        'level_int_3' => 'Identification des gammes et des modes',
        'level_int_4' => 'Dictée rythmique',
        'level_adv_title' => 'Avancé',
        'level_adv_period' => '1 an et plus',
        'level_adv_1' => 'Dictée mélodique',
        'level_adv_2' => 'Enchaînements d\'accords complexes',
        'level_adv_3' => 'Maîtrise de l\'oreille relative',
        'level_adv_4' => 'Harmonie modale',
        'ch6_takeaway' => 'La progression n\'est pas linéaire. Les déclics surviennent souvent brutalement après des plateaux. Faites confiance au processus, soyez présent chaque jour, et les résultats viendront.',
        'final_title' => 'Prêt à mettre ce guide en pratique ?',
        'final_subtitle' => 'Harmoniva vous permet de suivre exactement le travail structuré et adaptatif que recommande ce guide — dès le premier jour, entièrement gratuitement.',
        'final_button_1' => 'Commencer gratuitement',
        'final_button_2' => 'Voir le Parcours d\'apprentissage',
    ],
    'how_it_works' => [
