        'meta_description' => 'Piano virtuel gratuit dans votre navigateur : son réaliste, enregistrement, prise en charge des claviers MIDI et affichage des notes.',
        'og_title' => 'Studio de piano — Harmoniva',
        'og_description' => 'Jouez sur un vrai piano virtuel dans votre navigateur — son réaliste, enregistrement, prise en charge des claviers MIDI et affichage des notes.',
        'tw_title' => 'Studio de piano — Harmoniva',
