    'refund' => [
        'meta_title' => 'Politique de remboursement',
        'meta_description' => 'Politique de remboursement d\'Harmoniva : garantie de :days jours sur Premium, démarche de remboursement, droit de rétractation et délais.',
        'hero_title' => 'Politique de remboursement',
        'updated' => 'Dernière mise à jour : 31 juillet 2026',
        'summary_title' => 'En résumé',
        'summary_li1' => 'Essayez d\'abord Premium gratuitement pendant :trial jours — sans carte bancaire.',
        'summary_li2' => 'Vous avez payé Premium et changé d\'avis ? Écrivez-nous dans les :days jours suivant le prélèvement et vous êtes intégralement remboursé.',
        'summary_li3' => 'Cela couvre aussi un renouvellement annuel non voulu, si vous n\'avez pas utilisé Premium depuis ce renouvellement.',
        'summary_li4' => 'Les consommateurs de l\'UE, du Royaume-Uni et de Türkiye conservent en plus leurs droits légaux de rétractation.',
        'box_title' => 'Garantie satisfait ou remboursé de :days jours',
        'box_text' => 'Si Harmoniva Premium ne vous convient pas, écrivez-nous dans les :days jours suivant votre paiement et nous vous rembourserons intégralement. Vous n\'avez pas à vous justifier ni à résilier au préalable — nous nous chargeons de la résiliation dans le cadre du remboursement.',
        'commit_title' => 'Notre engagement de satisfaction',
        'commit_p1' => 'Nous avons créé Harmoniva parce que nous croyons sincèrement à ce qu\'il apporte aux musiciens. Si vous vous abonnez et constatez que cela ne vous convient pas, nous ne souhaitons pas garder votre argent. Cette politique est rédigée pour être équitable, précise et facile à mettre en œuvre.',
        'commit_p2' => 'Nous assumons aussi notre produit. Si quelque chose ne fonctionne pas comme prévu, ou si le service n\'a pas tenu ses promesses, contactez-nous avant de demander un remboursement — notre équipe support résout souvent le problème en quelques minutes, et nous préférons vous garder plutôt que garder votre paiement.',
        'trial_title' => 'Essayez avant de payer',
        'trial_p1' => 'Chaque compte démarre sur l\'offre gratuite, qui n\'expire jamais et ne demande jamais de carte. En plus de cela, chaque utilisateur peut activer un essai Premium gratuit de :trial jours — accès complet, aucun moyen de paiement requis, et il prend fin tout seul.',
        'trial_p2' => 'Comme l\'essai vous offre l\'expérience Premium complète avant tout paiement, la plupart des demandes de remboursement peuvent être évitées. Une période d\'essai est gratuite : il n\'y a donc rien à rembourser.',
        'g_title' => 'Garantie satisfait ou remboursé de :days jours',
        'g_intro' => 'Vous avez droit au <strong>remboursement intégral</strong> d\'un paiement Premium si vous nous contactez dans les <strong>:days jours calendaires</strong> suivant ce prélèvement. Cela couvre :',
        'g_li1' => 'Votre premier paiement mensuel Premium, quelle que soit la formule (élève, professeur ou école).',
        'g_li2' => 'Votre premier paiement annuel Premium, quelle que soit la formule.',
        'g_li3' => 'Un <strong>renouvellement annuel</strong> automatique, à condition que vous n\'ayez pas utilisé les fonctionnalités Premium depuis la date de renouvellement. C\'est le prélèvement qui surprend le plus souvent, nous le traitons donc comme un premier paiement.',
        'g_li4' => 'Tout prélèvement effectué par erreur — un double paiement, une formule que vous n\'avez pas choisie, ou un prélèvement après résiliation. Ceux-ci sont toujours remboursés intégralement, quel que soit le moment où vous les remarquez.',
        'g_p1' => 'Le délai de :days jours court à compter de la date de traitement du paiement, et non de votre première connexion. Si votre paiement est traité le 1er juin, le délai expire à la fin du 15 juin.',
        'g_p2' => 'La garantie est un droit par prélèvement, pas par compte, mais ce n\'est pas un moyen d\'utiliser Premium gratuitement indéfiniment : nous pouvons refuser une demande répétée émanant d\'un compte déjà remboursé pour la même formule. Si cela devait vous concerner, nous vous le dirions clairement et par écrit plutôt que de refuser en silence.',
        'law_title' => 'Vos droits légaux',
        'law_p1' => 'Rien dans cette politique ne limite les droits dont vous disposez en vertu du droit de la consommation applicable là où vous vivez. Lorsque ces droits sont plus protecteurs que la garantie ci-dessus, la loi prévaut.',
        'law_li1' => '<strong>Union européenne & Royaume-Uni</strong> : les consommateurs disposent d\'un droit de rétractation de 14 jours pour les contrats à distance. En commençant à utiliser Premium immédiatement après l\'achat, vous nous demandez de commencer la prestation pendant cette période ; vous pouvez tout de même vous rétracter dans les 14 jours, et lorsque nous avons déjà fourni le service nous pouvons déduire un montant proportionnel à ce que vous avez utilisé. En pratique, nous remboursons intégralement et n\'appliquons pas cette déduction.',
        'law_li2' => '<strong>Türkiye</strong> : en vertu de la loi sur la protection des consommateurs (n° 6502) et du règlement sur les contrats à distance, vous disposez d\'un droit de rétractation de 14 jours. Le contenu numérique fourni immédiatement avec votre consentement en est normalement exclu — nous renonçons à cette exclusion et honorons la rétractation dans les conditions ci-dessus.',
        'law_li3' => '<strong>États-Unis</strong> : les droits au remboursement varient selon les États, et certains accordent aux acheteurs des droits d\'annulation supplémentaires. Cette politique s\'applique à l\'échelle nationale comme minimum ; tout droit plus étendu prévu par la loi de votre État reste intact.',
        'law_li4' => '<strong>Partout ailleurs</strong> : si le droit de la consommation local vous accorde un délai plus long ou un droit plus large que cette politique, dites-le-nous et nous l\'appliquerons.',
        'law_p2' => 'Pour exercer un droit légal de rétractation, un simple e-mail indiquant que vous vous rétractez du contrat suffit — aucun formulaire ni formulation particulière n\'est exigé.',
        'req_title' => 'Comment demander un remboursement',
        'req_intro' => 'Demander un remboursement est simple et prend moins de deux minutes :',
        'req_s1_title' => 'Écrivez-nous dans le délai imparti',
        'req_s1_desc' => 'Envoyez un e-mail à :email avec pour objet <strong>« Refund Request »</strong>.',
        'req_s2_title' => 'Indiquez l\'e-mail de votre compte',
        'req_s2_desc' => 'Communiquez-nous l\'adresse e-mail de votre compte Harmoniva et la date approximative du paiement. Si vous souhaitez expliquer ce qui n\'a pas fonctionné, nous lisons chaque mot — mais c\'est facultatif et cela n\'influence jamais la décision.',
        'req_s3_title' => 'Nous confirmons et traitons',
        'req_s3_desc' => 'Nous confirmons votre demande sous 1 jour ouvré et la traitons immédiatement. Voir « Procédure et délais de remboursement » ci-dessous pour savoir combien de temps l\'argent met à vous parvenir.',
        'req_note' => 'Vous n\'avez pas besoin de résilier votre abonnement avant de demander un remboursement — la résiliation fait partie de la procédure. Si vous résiliez vous-même d\'abord, cela ne pose aucun problème : résilier ne fait pas perdre votre droit au remboursement, tant que vous nous contactez dans le délai.',
        'nr_title' => 'Ce qui n\'est pas couvert',
        'nr_intro' => 'En dehors des cas listés ci-dessus, les remboursements ne sont généralement pas possibles dans les situations suivantes :',
        'nr_li1' => '<strong>Demandes après le délai de :days jours</strong> : une fois le délai écoulé, un paiement n\'est plus remboursable — sauf s\'il s\'agit d\'une erreur de facturation ou d\'un manquement documenté de notre part, que nous corrigeons quel que soit le moment.',
        'nr_li2' => '<strong>Renouvellements mensuels utilisés</strong> : si un renouvellement mensuel est prélevé et que vous avez travaillé sur Premium pendant la nouvelle période, nous ne le remboursons pas. Vous pouvez résilier à tout moment pour arrêter le suivant.',
        'nr_li3' => '<strong>Périodes partielles</strong> : nous ne calculons pas de prorata sur un reliquat non utilisé. Lorsque vous résiliez en cours de cycle, vous conservez l\'accès Premium complet jusqu\'à la fin de la période payée : rien n\'est perdu.',
        'nr_li4' => '<strong>Comptes fermés pour manquement</strong> : si nous résilions un compte pour violation de nos conditions d\'utilisation, la valeur restante de l\'abonnement n\'est pas remboursée.',
        'nr_li5' => '<strong>Offre gratuite et essai</strong> : l\'offre gratuite et l\'essai de :trial jours ne coûtent rien, il n\'y a donc rien à rembourser.',
        'nr_p1' => 'Cette liste n\'est pas un mur. Si vous estimez avoir une demande légitime qui n\'y figure pas — un prélèvement jamais autorisé, un problème technique qui vous a empêché d\'utiliser ce que vous avez payé, un paiement effectué par un proche à votre insu — écrivez-nous. Nous examinons ces cas individuellement et les tranchons de bonne foi.',
        'app_title' => 'Achats via l\'App Store ou Google Play',
        'app_p1' => 'Si vous vous abonnez dans une application mobile Harmoniva via un achat intégré, Apple ou Google est le vendeur officiel de cette transaction — nous ne recevons jamais vos données de paiement et ne pouvons pas la rembourser nous-mêmes.',
        'app_li1' => '<strong>App Store d\'Apple</strong> : demandez un remboursement sur <em>reportaproblem.apple.com</em> ou depuis les Réglages de votre appareil. Apple statue selon sa propre politique.',
        'app_li2' => '<strong>Google Play</strong> : demandez un remboursement depuis votre historique de commandes Google Play ou via le support Google Play. Google statue selon sa propre politique.',
        'app_li3' => '<strong>Gérer l\'abonnement</strong> : un abonnement intégré doit également être résilié dans le compte du store qui l\'a acheté — résilier dans Harmoniva n\'arrête pas la facturation du store.',
        'app_p2' => 'Si le store refuse votre demande et que vous estimez que la garantie de :days jours ci-dessus devrait s\'appliquer, contactez-nous avec votre numéro de commande. Nous ne pouvons pas annuler un prélèvement du store, mais nous pouvons vous offrir à nos frais un accès Premium équivalent ou un crédit, pour que vous ne soyez pas lésé.',
        'app_p3' => 'Les abonnements achetés sur notre site sont facturés par nous et relèvent entièrement de cette politique.',
        'tl_title' => 'Procédure et délais de remboursement',
        'tl_intro' => 'Une fois un remboursement approuvé :',
        'tl_li1' => 'Nous résilions l\'abonnement et basculons le compte sur l\'offre gratuite. Votre historique de pratique, vos progrès et vos modèles enregistrés sont conservés — seules les fonctionnalités Premium s\'arrêtent.',
        'tl_li2' => 'Le remboursement est renvoyé sur le moyen de paiement d\'origine via notre prestataire de paiement. Nous ne pouvons pas l\'envoyer sur une autre carte ou un autre compte.',
        'tl_li3' => 'Vous recevez un e-mail confirmant le remboursement et son montant.',
        'tl_box_title' => 'Délai habituel : 5 à 10 jours ouvrés',
        'tl_box_desc' => 'Les remboursements apparaissent généralement sur votre relevé de carte ou bancaire dans les 5 à 10 jours ouvrés suivant notre date de traitement. Le délai exact est fixé par votre émetteur de carte ou votre banque et échappe à notre contrôle ; certaines banques prennent jusqu\'à 14 jours ouvrés, et quelques-unes affichent le remboursement à la date de la transaction initiale.',
        'tl_note' => 'Si le remboursement n\'est pas arrivé après 14 jours ouvrés, vérifiez d\'abord auprès de votre banque, puis contactez-nous — nous relancerons notre prestataire de paiement et vous enverrons la référence de transaction.',
        'cb_title' => 'Oppositions et litiges de paiement',
        'cb_p1' => 'Si vous ne reconnaissez pas un prélèvement, écrivez-nous avant d\'ouvrir un litige auprès de votre banque. Presque tous les cas que nous voyons sont un renouvellement annuel ou l\'achat d\'un proche, et nous pouvons généralement rembourser le jour même — bien plus vite qu\'une opposition, qui prend en général 6 à 12 semaines à se résoudre.',
        'cb_p2' => 'Lorsqu\'une opposition est ouverte, nous répondons avec nos justificatifs de transaction. Pendant la durée du litige, nous pouvons suspendre l\'accès Premium du compte jusqu\'à sa résolution, et un compte ayant fait l\'objet d\'une opposition peut devoir régulariser son solde avant de se réabonner. Nous ne répercutons pas les frais de litige sur les utilisateurs.',
        'tp_title' => 'Cours, professeurs et licences scolaires',
        'tp_p1' => 'Harmoniva met en relation des élèves avec des professeurs indépendants et des écoles de musique, mais nous ne sommes pas partie aux accords de cours conclus entre eux. Les honoraires de cours particuliers, de rendez-vous ou de scolarité convenus via un professeur ou une école sont réglés directement à ce professeur ou à cette école selon leurs propres conditions — nous ne les encaissons pas et cette politique ne les couvre pas. Renseignez-vous auprès de votre professeur ou de votre école sur leurs conditions d\'annulation et de remboursement.',
        'tp_p2' => 'Cette politique couvre en revanche les abonnements Harmoniva eux-mêmes, y compris les formules professeurs et écoles achetées chez nous. Lorsqu\'une école ou un établissement achète des places pour ses membres dans le cadre d\'un accord écrit distinct, les conditions de remboursement de cet accord s\'appliquent et priment sur cette page.',
        'tp_p3' => 'Les crédits promotionnels, les périodes Premium offertes ou en cadeau, les coupons et les remises n\'ont aucune valeur monétaire et ne sont ni remboursables ni échangeables contre de l\'argent.',
        'cur_title' => 'Devise, taxes et frais',
        'cur_p1' => 'Les prix sont facturés en dollars américains sauf mention contraire au moment du paiement. Les remboursements sont effectués dans la devise d\'origine et pour le montant initialement prélevé, taxes que nous avons collectées comprises.',
        'cur_p2' => 'Si votre carte est libellée dans une autre devise, le montant qui revient sur votre compte peut différer légèrement de celui qui en est parti, car votre banque applique son propre taux de change à chaque conversion. Les frais de transaction à l\'étranger prélevés par votre banque sont fixés par elle et ne peuvent pas être remboursés par nous.',
        'ch_title' => 'Modifications de cette politique',
        'ch_p1' => 'Nous pouvons faire évoluer cette politique de remboursement à mesure que le service change. La version en vigueur au moment de votre paiement est celle qui régit ce paiement : une modification ultérieure ne peut donc jamais réduire un droit au remboursement déjà acquis. Les changements substantiels sont annoncés par e-mail ou par notification dans l\'application avant leur entrée en vigueur, et la date de « dernière mise à jour » en haut de cette page reflète toujours la version en cours.',
        'contact_title' => 'Nous contacter',
        'contact_intro' => 'Une question sur un remboursement, ou un prélèvement qui vous semble erroné ? Écrivez-nous — une personne lit chaque message.',
        'contact_box_title' => 'Support remboursement et facturation',
        'contact_box_desc' => 'Délai de réponse : sous 1 jour ouvré, du lundi au vendredi.',
        'contact_address' => 'Harmoniva est exploité par Softchain Solutions, 8 The Green STE B, Dover, DE 19901, États-Unis.',
        'contact_footer' => 'Cette politique de remboursement fait partie de nos :terms et y est soumise. Pour les cycles de facturation, les renouvellements et la résiliation, consultez nos :subscription.',
        'contact_terms_link' => 'Conditions d\'utilisation',
        'contact_subscription_link' => 'Conditions d\'abonnement',
    ],
    'subscription' => [
        'meta_title' => 'Conditions d\'abonnement',
        'meta_description' => 'Conditions d\'abonnement Harmoniva : formules, facturation, reconduction, résiliation et essai gratuit, expliqués simplement.',
        'hero_title' => 'Conditions d\'abonnement',
        'updated' => 'Dernière mise à jour : 1er juin 2026',
        'intro' => 'Ces conditions d\'abonnement complètent nos :terms et régissent la facturation, la reconduction et la résiliation des abonnements payants. Pour toute question, écrivez-nous à :email.',
        'terms_link' => 'Conditions d\'utilisation',
        'plans_title' => 'Formules d\'abonnement',
        'plans_intro' => 'Harmoniva propose les niveaux d\'abonnement suivants :',
        'plan_free_title' => 'Gratuit',
        'plan_free_desc' => 'Sans frais. Accès à 3 exercices par type et par jour, 3 modèles enregistrés et les types d\'exercices standard. Aucune carte bancaire requise.',
        'plan_premium_title' => 'Premium',
        'plan_premium_desc' => 'Exercices illimités, parcours d\'apprentissage IA, configuration avancée, modèles illimités. Disponible au mois ou à l\'année.',
        'plan_ts_title' => 'Professeurs & écoles',
        'plan_ts_desc' => 'Toutes les fonctionnalités Premium, plus les tableaux de bord professeurs, la gestion des élèves, les licences groupées et un accompagnement institutionnel. Tarif sur demande.',
        'plans_footer' => 'Les prix en vigueur pour toutes les formules figurent sur notre :pricing. Tous les prix sont en dollars américains, sauf mention contraire.',
        'pricing_link' => 'page Tarifs',
        'cycles_title' => 'Cycles de facturation',
        'cycles_intro' => 'Les abonnements payants sont proposés selon deux cycles de facturation :',
        'cycles_li1' => '<strong>Mensuel</strong> : vous êtes prélevé une fois par mois, à la date anniversaire du début de votre abonnement.',
        'cycles_li2' => '<strong>Annuel</strong> : vous êtes prélevé une fois par an, d\'avance, pour la totalité des 12 mois. Les formules annuelles sont proposées à tarif réduit par rapport au mensuel équivalent.',
        'cycles_p1' => 'Votre première date de facturation est celle de votre souscription. Elle reste identique chaque mois ou chaque année tant que vous ne changez pas de formule. En cas de passage à une formule supérieure en cours de cycle, vous êtes prélevé au prorata pour le reste de la période en cours.',
        'renewal_title' => 'Reconduction automatique',
        'renewal_p1' => 'Les abonnements se reconduisent automatiquement à la fin de chaque cycle de facturation, sauf résiliation avant la date de reconduction. En vous abonnant, vous autorisez Harmoniva (via Stripe) à prélever votre moyen de paiement de façon récurrente.',
        'renewal_p2' => 'Nous vous envoyons un e-mail de rappel au moins 7 jours avant la reconduction d\'une formule annuelle, ce qui vous laisse le temps de résilier si vous ne souhaitez pas continuer. Les formules mensuelles se reconduisent sans rappel spécifique, mais votre échéancier reste toujours visible dans les paramètres de votre compte.',
        'renewal_p3' => 'Pour empêcher la reconduction, résiliez votre abonnement au moins 24 heures avant la prochaine date de facturation. Voir « Politique de résiliation » ci-dessous pour la marche à suivre.',
        'price_title' => 'Changements de prix',
        'price_p1' => 'Nous nous réservons le droit de modifier les prix des abonnements à tout moment. Si nous modifions le prix de votre formule actuelle, nous vous en informerons par e-mail au moins 30 jours avant l\'entrée en vigueur.',
        'price_p2' => 'Votre nouveau tarif s\'appliquera à votre prochaine date de reconduction après le changement. Si vous ne souhaitez pas payer le nouveau prix, vous pouvez résilier avant cette date. La poursuite de l\'utilisation du service après le changement de prix vaut acceptation du nouveau tarif.',
        'cancel_title' => 'Politique de résiliation',
        'cancel_intro' => 'Vous pouvez résilier votre abonnement à tout moment. Pour résilier :',
        'cancel_s1' => 'Connectez-vous à votre compte Harmoniva.',
        'cancel_s2' => 'Allez dans <strong>Paramètres du compte → Abonnement</strong>.',
        'cancel_s3' => 'Cliquez sur « Résilier l\'abonnement » et suivez les instructions.',
        'cancel_p1' => 'Vous pouvez également écrire à :email pour demander la résiliation. Nous traitons toutes les demandes sous 1 jour ouvré.',
        'cancel_p2' => 'Après résiliation, votre abonnement reste actif jusqu\'à la fin de la période payée en cours. Vous conservez l\'accès complet aux fonctionnalités Premium jusqu\'à cette date. Ensuite, votre compte revient à l\'offre gratuite.',
        'cancel_p3' => 'La résiliation ne déclenche pas automatiquement un remboursement. Consultez notre :refund pour savoir dans quels cas un remboursement est possible.',
        'refund_link' => 'Politique de remboursement',
        'refunds_title' => 'Remboursements',
        'refunds_intro' => 'Nos conditions de remboursement sont détaillées dans notre :refund. En résumé :',
        'refunds_li1' => 'Les nouveaux abonnés ont droit à un remboursement intégral dans les 14 jours suivant leur premier paiement.',
        'refunds_li2' => 'Aucun remboursement n\'est possible après 14 jours ni pour des périodes de facturation partielles.',
        'refunds_li3' => 'Pour demander un remboursement, écrivez à :email dans le délai imparti.',
        'ud_title' => 'Changements de formule',
        'ud_up_title' => 'Passer à une formule supérieure',
        'ud_up_p' => 'Si vous passez d\'une formule mensuelle à une formule annuelle, ou de Gratuit à Premium, vous êtes prélevé immédiatement. Pour un passage entre formules payantes en cours de cycle, vous êtes prélevé au prorata de la différence de prix pour le reste du cycle de facturation en cours.',
        'ud_down_title' => 'Passer à une formule inférieure',
        'ud_down_p1' => 'Si vous passez d\'une formule annuelle à une formule mensuelle, ou de Premium à Gratuit, le changement prend effet à la fin de votre cycle de facturation en cours. Aucun remboursement au prorata n\'est accordé pour le temps non utilisé de votre formule actuelle, sauf si vous êtes dans le délai de remboursement de 14 jours.',
        'ud_down_p2' => 'Si vous repassez à l\'offre gratuite, vos fonctionnalités Premium restent actives jusqu\'à la fin de la période payée en cours, puis sont désactivées. Vos données de pratique sont conservées.',
        'trial_title' => 'Essai gratuit',
        'trial_p1' => 'Chaque compte peut démarrer un essai gratuit de Premium de :days jours. <strong>Aucune carte bancaire ni coordonnée de paiement n\'est requise pour commencer, et aucun moyen de paiement n\'est enregistré.</strong>',
        'trial_p2' => '<strong>Vous ne serez pas prélevé à la fin de l\'essai.</strong> Comme nous ne collectons jamais de coordonnées de paiement en amont, il n\'y a rien à facturer ni à résilier. À la fin de la période d\'essai, votre compte revient simplement à l\'offre gratuite, vos fonctionnalités Premium sont désactivées et vos données de pratique sont conservées. Vous pouvez ensuite vous abonner quand vous le souhaitez si vous voulez poursuivre avec Premium.',
        'trial_p3' => 'L\'essai gratuit est disponible une fois par compte. Nous nous réservons le droit de vérifier l\'éligibilité et de retirer l\'accès à l\'essai si nous constatons un usage abusif de ses conditions.',
        'trial_box' => '<strong>Des questions sur votre abonnement ?</strong> Écrivez-nous à :email — nous serons ravis de vous aider.',
    ],
    'cookie' => [
        'meta_title' => 'Politique relative aux cookies',
        'meta_description' => 'Découvrez comment Harmoniva utilise les cookies et technologies similaires sur harmoniva.app.',
        'hero_title' => 'Politique relative aux cookies',
        'updated' => 'Dernière mise à jour : 1er juin 2026',
        'what_title' => 'Que sont les cookies ?',
        'what_p1' => 'Les cookies sont de petits fichiers texte déposés sur votre appareil (ordinateur, téléphone ou tablette) lorsque vous visitez un site web. Ils sont largement utilisés pour faire fonctionner les sites plus efficacement, mémoriser vos préférences et fournir des informations aux éditeurs.',
        'what_p2' => 'Les cookies peuvent être des « cookies de session », qui expirent à la fermeture du navigateur, ou des « cookies persistants », qui restent sur votre appareil pendant une durée définie ou jusqu\'à ce que vous les supprimiez. Nous utilisons également des technologies similaires, comme le stockage local et le stockage de session, à des fins fonctionnelles.',
        'what_p3' => 'En utilisant harmoniva.app, vous consentez à l\'utilisation de cookies telle que décrite dans cette politique. Vous pouvez gérer ou désactiver les cookies à tout moment via les paramètres de votre navigateur, même si cela peut affecter certaines fonctionnalités du service.',
        'types_title' => 'Types de cookies que nous utilisons',
        'type_essential_title' => 'Cookies essentiels',
        'type_essential_lead' => '<strong>Nécessaires au fonctionnement du service.</strong> Ils ne peuvent pas être désactivés.',
        'type_essential_desc' => 'Ces cookies sont indispensables pour vous connecter, naviguer sur la plateforme et utiliser les fonctionnalités principales. Sans eux, le service ne peut pas fonctionner. Ils ne collectent aucune information personnelle à des fins marketing.',
        'type_perf_title' => 'Cookies de performance et d\'analyse',
        'type_perf_lead' => '<strong>Nous aident à comprendre comment vous utilisez le service.</strong>',
        'type_perf_desc' => 'Ces cookies recueillent des informations sur les pages que vous visitez, le temps que vous y passez et les erreurs rencontrées. Ces informations sont agrégées et anonymisées lorsque c\'est possible. Nous les utilisons pour améliorer les performances et le contenu du service.',
        'type_func_title' => 'Cookies fonctionnels',
        'type_func_lead' => '<strong>Mémorisent vos préférences et vos réglages.</strong>',
        'type_func_desc' => 'Ces cookies permettent au service de retenir vos choix — comme votre préférence de langue ou de région — et de proposer des fonctionnalités enrichies et personnalisées. Ils peuvent être déposés par nous ou par des prestataires tiers dont nous avons intégré les services.',
        'type_mkt_title' => 'Cookies marketing',
        'type_mkt_lead' => '<strong>Non utilisés actuellement.</strong>',
        'type_mkt_desc' => 'Nous n\'utilisons pas de cookies marketing ou publicitaires à l\'heure actuelle. Nous ne déposons aucun cookie de suivi pour des régies publicitaires tierces, du reciblage ou du profilage comportemental.',
        'table_title' => 'Les cookies que nous utilisons',
        'table_intro' => 'Le tableau suivant décrit les cookies spécifiques déposés par harmoniva.app :',
        'col_name' => 'Nom du cookie',
        'col_purpose' => 'Finalité',
        'col_duration' => 'Durée',
        'col_type' => 'Type',
        'dur_session' => 'Session',
        'dur_5y' => '5 ans',
        'dur_1y' => '1 an',
        'dur_ga' => '2 ans / 24 h',
        'type_essential_badge' => 'Essentiel',
        'type_functional_badge' => 'Fonctionnel',
        'type_analytics_badge' => 'Analyse',
        'p_session' => 'Maintient votre session de connexion. Vous identifie comme utilisateur connecté d\'une page à l\'autre.',
        'p_xsrf' => 'Protection contre la falsification de requête intersite. Empêche l\'envoi de formulaires non autorisés en votre nom.',
        'p_remember' => 'Jeton « Se souvenir de moi ». Vous garde connecté d\'une session de navigateur à l\'autre lorsque vous cochez « Se souvenir de moi » à la connexion.',
        'p_locale' => 'Enregistre votre langue ou région d\'interface préférée afin qu\'elle soit conservée d\'une session à l\'autre.',
        'p_csrf' => 'Jeton CSRF supplémentaire utilisé par les composants Livewire pour sécuriser les interactions en temps réel.',
        'p_ga' => 'Google Analytics — sert à distinguer les utilisateurs et à comptabiliser les visites de pages de façon agrégée. Non associé à votre identité.',
        'manage_title' => 'Comment gérer les cookies',
        'manage_p1' => 'La plupart des navigateurs permettent de contrôler les cookies depuis leurs paramètres. Vous les trouverez généralement dans le menu « Options », « Préférences » ou « Paramètres » de votre navigateur. Vous pouvez bloquer ou supprimer les cookies à tout moment.',
        'manage_note' => '<strong>À noter :</strong> désactiver les cookies essentiels vous empêchera de vous connecter et d\'utiliser les fonctionnalités principales du service. En cas de préoccupation liée à la vie privée, nous vous conseillons de ne désactiver que les cookies non essentiels (analyse, fonctionnels).',
        'manage_sub' => 'Paramètres des cookies dans le navigateur',
        'contact_title' => 'Des questions sur notre usage des cookies ?',
        'contact_intro' => 'Si vous avez des questions sur cette politique relative aux cookies ou sur notre usage des cookies, contactez-nous :',
        'contact_company' => 'Softchain Solutions — Harmoniva',
        'contact_address' => '8 The Green STE B, Dover, DE 19901, États-Unis',
        'contact_footer' => 'Cette politique relative aux cookies peut être mise à jour de temps à autre. Nous publierons la version actualisée sur cette page avec une date de « dernière mise à jour » révisée.',
