    'terms' => [
        'meta_title' => 'Conditions d\'utilisation',
        'meta_description' => 'Conditions d\'utilisation d\'Harmoniva. Merci de lire attentivement ces conditions avant d\'utiliser notre plateforme de formation de l\'oreille assistée par IA.',
        'hero_title' => 'Conditions d\'utilisation',
        'updated' => 'Dernière mise à jour : 1er juin 2026',
        'toc_title' => 'Sommaire',
        'toc_acceptance' => '1. Acceptation des conditions',
        'toc_description' => '2. Description du service',
