        'rights_all_li3' => '<strong>Suppression</strong> — demander la suppression de votre compte et de vos données personnelles.',
        'rights_all_li4' => '<strong>Opposition</strong> — vous désinscrire des e-mails marketing à tout moment via le lien de désinscription présent dans chaque e-mail ou depuis les paramètres de votre compte.',
        'rights_ccpa_title' => 'Résidents de Californie (CCPA)',
